SELECT fn_cp_import_case('ordre-journaliste-presence-couverture', '{"slug": "ordre-journaliste-presence-couverture", "title": "Il filme le dispositif et demande votre matricule", "theme_slug": "ordre-public", "difficulty": "moyen", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 16 heures. Lors d''une manifestation, un homme muni d''une caméra filme ouvertement le dispositif de sécurité que vous formez avec vos collègues, puis s''approche pour vous demander directement votre numéro de matricule, cette démarche s''inscrivant dans le cadre légitime de son travail de couverture journalistique de cet événement. Cette situation, où votre réflexe défensif pourrait naturellement vous inciter à percevoir cette caméra et cette demande comme une intrusion, doit céder la place à une reconnaissance claire de la liberté d''informer qui encadre légalement ce type d''activité de presse.\n\nCette configuration, caractéristique du rapport entre les forces de l''ordre et les professionnels de la presse lors de ce type d''événement, nécessite un comportement qui ne traite pas ce journaliste comme une menace potentielle mais reconnaît pleinement la légitimité de son travail de couverture médiatique.\n\nCette situation impose de ne pas entraver ce travail de presse tout en restant courtoise dans votre réponse à sa demande, cette conciliation entre votre propre réserve professionnelle et le respect de cette liberté d''informer restant essentielle dans ce type d''interaction.", "questions": [{"position": 1, "max_points": 5, "label": "Comment reconnaissez-vous la légitimité de ce travail journalistique sans céder à un réflexe défensif ?", "hint": "Cette caméra et cette demande, bien que pouvant naturellement susciter une certaine réserve, s''inscrivent dans un cadre légal légitime qui mérite d''être pleinement reconnu.", "perfect": "Je reconnais explicitement la légitimité de ce travail de couverture journalistique, cette activité s''inscrivant dans un cadre légal qui encadre la liberté d''informer lors de ce type d''événement.\n\nJe reste attentive à ne pas laisser mon réflexe défensif naturel orienter mon comportement envers ce journaliste, cette caméra ne constituant pas en elle-même une menace justifiant une réaction de méfiance.\n\nJe reste courtoise dans cet échange, cette attitude professionnelle restant appropriée face à une démarche qui relève d''un exercice légitime de son activité professionnelle.\n\nJe garde à l''esprit que cette présence de la presse contribue à la transparence de l''action publique lors de ce type d''événement, cette dimension méritant d''être intégrée dans ma propre appréciation de la situation.", "points": [{"position": 1, "label": "Reconnaître explicitement la légitimité de ce travail journalistique", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : cadre légal encadrant la liberté d''informer.", "groups": [{"position": 1, "keywords": ["légitimité reconnue", "cadre légal", "liberté d''informer"]}]}, {"position": 2, "label": "Ne pas laisser le réflexe défensif orienter le comportement", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Caméra ne constituant pas une menace en elle-même.", "groups": [{"position": 1, "keywords": ["pas de réflexe défensif", "caméra non menaçante", "comportement maîtrisé"]}]}, {"position": 3, "label": "Rester courtoise face à cette démarche professionnelle légitime", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Attitude professionnelle appropriée.", "groups": [{"position": 1, "keywords": ["courtoisie maintenue", "démarche légitime", "attitude professionnelle"]}]}, {"position": 4, "label": "Garder à l''esprit la contribution de la presse à la transparence", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Dimension intégrée dans l''appréciation de la situation.", "groups": [{"position": 1, "keywords": ["transparence de l''action publique", "presse contributive", "appréciation intégrée"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment répondez-vous à sa demande de communication de votre matricule ?", "hint": "Cette demande, qui s''inscrit dans un cadre légal spécifique, mérite une réponse adaptée qui concilie vos obligations professionnelles avec le respect de ce cadre.", "perfect": "Je réponds à cette demande conformément au cadre applicable à ce type de sollicitation, cette information réglementée devant être communiquée selon les modalités prévues à cet effet.\n\nJe reste factuelle et posée dans cette réponse, sans manifester d''agacement ou de réticence excessive face à une demande qui s''inscrit dans un cadre légal légitime.\n\nJe reste attentive à ne pas percevoir cette demande comme une remise en cause personnelle, cette sollicitation relevant d''une pratique journalistique habituelle plutôt que d''une défiance à mon égard.\n\nJe reste professionnelle dans l''ensemble de cet échange, cette rigueur restant importante indépendamment de mon ressenti personnel face à cette sollicitation particulière.", "points": [{"position": 1, "label": "Répondre conformément au cadre applicable à cette sollicitation", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : information réglementée communiquée selon les modalités prévues.", "groups": [{"position": 1, "keywords": ["cadre applicable", "information réglementée", "modalités prévues"]}]}, {"position": 2, "label": "Rester factuelle et posée sans agacement excessif", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Demande s''inscrivant dans un cadre légal légitime.", "groups": [{"position": 1, "keywords": ["factuelle et posée", "pas d''agacement", "cadre légal légitime"]}]}, {"position": 3, "label": "Ne pas percevoir cette demande comme une remise en cause personnelle", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Pratique journalistique habituelle plutôt que défiance.", "groups": [{"position": 1, "keywords": ["pas de remise en cause", "pratique habituelle", "pas de défiance"]}]}, {"position": 4, "label": "Rester professionnelle indépendamment de son ressenti personnel", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Rigueur importante malgré la sollicitation particulière.", "groups": [{"position": 1, "keywords": ["professionnalisme maintenu", "ressenti personnel écarté", "rigueur importante"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment veillez-vous à ne pas entraver ce travail de presse pour la suite de cette manifestation ?", "hint": "Au-delà de cette interaction ponctuelle, votre comportement général envers ce journaliste durant le reste de cette manifestation doit continuer à respecter la liberté d''informer qui encadre son activité.", "perfect": "Je m''assure de ne pas entraver physiquement sa capacité à filmer ce dispositif, cette liberté de captation restant protégée tant qu''elle ne compromet pas la sécurité de l''intervention.\n\nJe reste attentive à ne pas adopter, pour la suite de cette manifestation, un comportement différent envers ce journaliste du seul fait de cet échange initial, cette continuité restant importante pour la crédibilité de mon professionnalisme.\n\nJe reste disponible si ce journaliste avait d''autres questions légitimes durant la suite de cette manifestation, cette ouverture restant appropriée dans le respect de son activité professionnelle.\n\nJe signale si nécessaire à mes collègues la présence de ce journaliste, cette information pouvant faciliter une gestion coordonnée et cohérente de cette présence médiatique par l''ensemble du dispositif.", "points": [{"position": 1, "label": "S''assurer de ne pas entraver physiquement sa capacité à filmer", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : liberté de captation protégée sauf compromission de sécurité.", "groups": [{"position": 1, "keywords": ["captation protégée", "pas d''entrave physique", "sécurité préservée"]}]}, {"position": 2, "label": "Ne pas adopter un comportement différent pour la suite de la manifestation", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Continuité importante pour la crédibilité professionnelle.", "groups": [{"position": 1, "keywords": ["comportement constant", "crédibilité maintenue", "continuité importante"]}]}, {"position": 3, "label": "Rester disponible pour d''autres questions légitimes", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Ouverture appropriée dans le respect de son activité.", "groups": [{"position": 1, "keywords": ["disponibilité maintenue", "questions légitimes", "activité respectée"]}]}, {"position": 4, "label": "Signaler la présence de ce journaliste aux collègues si nécessaire", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Gestion coordonnée de cette présence médiatique.", "groups": [{"position": 1, "keywords": ["présence signalée", "gestion coordonnée", "dispositif cohérent"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('ordre-elu-local-sur-place-demande', '{"slug": "ordre-elu-local-sur-place-demande", "title": "L''adjoint au maire demande de laisser la sono jusqu''à 2 heures", "theme_slug": "ordre-public", "difficulty": "moyen", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 22 heures. Lors d''une fête locale, l''adjoint au maire présent sur place vous demande directement de laisser la sonorisation fonctionner jusqu''à 2 heures du matin, dépassant ainsi largement l''horaire normalement prévu par les autorisations habituelles pour ce type d''événement festif, cette sollicitation s''appuyant implicitement sur sa qualité d''élu local pour peser sur votre décision de terrain. Cette pression institutionnelle, exercée par une personnalité dont l''autorité pourrait naturellement vous inciter à céder à cette demande, ne doit pourtant pas vous conduire à prendre seule une décision qui dépasse le cadre normalement applicable à cet événement.\n\nCette situation, où la qualité du demandeur ne doit pas influencer indûment votre appréciation de ce qui relève strictement de votre rôle sur le terrain, nécessite de rendre compte de cette sollicitation particulière plutôt que d''accéder directement à cette demande sur la seule autorité de cet élu.\n\nCette configuration impose de ne pas céder à la qualité de ce demandeur tout en rendant compte de cette situation à votre hiérarchie, cette remontée d''information restant essentielle pour qu''une décision appropriée puisse être prise concernant cette demande de dépassement.", "questions": [{"position": 1, "max_points": 5, "label": "Comment ne cédez-vous pas à cette pression institutionnelle exercée par la qualité de cet élu ?", "hint": "La qualité de cet élu, aussi respectable soit son autorité locale, ne doit pas influencer indûment votre appréciation de ce qui relève du cadre normalement applicable à cet événement.", "perfect": "Je reste attentive à ne pas céder à cette pression du seul fait de la qualité d''élu de cette personne, cette autorité locale ne me conférant pas la légitimité de dépasser seule le cadre normalement applicable.\n\nJe reste courtoise et respectueuse envers cet adjoint au maire, cette réserve professionnelle n''impliquant pas un manque de considération pour sa fonction institutionnelle.\n\nJe lui explique clairement que cette décision dépasse mon niveau de responsabilité sur le terrain, cette clarification restant nécessaire pour qu''il comprenne les limites de ce que je peux personnellement décider.\n\nJe reste factuelle sur le cadre horaire normalement applicable à cet événement, cette information objective devant orienter cet échange indépendamment de la pression exercée.", "points": [{"position": 1, "label": "Ne pas céder à la pression du seul fait de la qualité d''élu", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : autorité locale ne conférant pas de légitimité de dépassement.", "groups": [{"position": 1, "keywords": ["pas de cession", "qualité d''élu", "légitimité non conférée"]}]}, {"position": 2, "label": "Rester courtoise et respectueuse envers cet adjoint au maire", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Réserve professionnelle sans manque de considération.", "groups": [{"position": 1, "keywords": ["courtoisie maintenue", "réserve professionnelle", "considération de la fonction"]}]}, {"position": 3, "label": "Expliquer clairement que cette décision dépasse son niveau de responsabilité", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Clarification des limites de sa décision personnelle.", "groups": [{"position": 1, "keywords": ["niveau de responsabilité", "limites clarifiées", "décision non personnelle"]}]}, {"position": 4, "label": "Rester factuelle sur le cadre horaire normalement applicable", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Information objective orientant l''échange.", "groups": [{"position": 1, "keywords": ["cadre horaire factuel", "information objective", "échange orienté"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment rendez-vous compte de cette situation particulière à votre hiérarchie ?", "hint": "Cette sollicitation par un élu local nécessite une remontée d''information précise pour permettre à votre hiérarchie d''apprécier la suite appropriée à donner à cette demande.", "perfect": "Je transmets sans délai à ma hiérarchie cette demande de dépassement horaire formulée par cet adjoint au maire, cette information devant remonter rapidement compte tenu de la qualité du demandeur.\n\nJe décris factuellement les termes exacts de cette sollicitation, sans dramatiser ni minimiser cette pression institutionnelle exercée par cette personnalité locale.\n\nJe reste attentive à ne pas laisser transparaître dans mon compte rendu une quelconque intimidation de ma part, cette objectivité restant nécessaire pour une appréciation appropriée de la situation.\n\nJe reste disponible pour toute clarification complémentaire que ma hiérarchie pourrait souhaiter sur les circonstances précises de cette demande.", "points": [{"position": 1, "label": "Transmettre sans délai cette demande de dépassement horaire", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : remontée rapide compte tenu de la qualité du demandeur.", "groups": [{"position": 1, "keywords": ["demande transmise", "qualité du demandeur", "remontée rapide"]}]}, {"position": 2, "label": "Décrire factuellement les termes exacts de cette sollicitation", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Sans dramatiser ni minimiser cette pression.", "groups": [{"position": 1, "keywords": ["termes exacts décrits", "pas de dramatisation", "pas de minimisation"]}]}, {"position": 3, "label": "Ne pas laisser transparaître une quelconque intimidation personnelle", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Objectivité nécessaire pour l''appréciation.", "groups": [{"position": 1, "keywords": ["pas d''intimidation transparente", "objectivité maintenue", "appréciation appropriée"]}]}, {"position": 4, "label": "Rester disponible pour toute clarification complémentaire", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Circonstances précises de la demande.", "groups": [{"position": 1, "keywords": ["disponibilité maintenue", "clarification possible", "circonstances précises"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment gérez-vous la situation pratique de cet événement en attendant une décision appropriée ?", "hint": "En attendant la décision qui sera prise suite à votre compte rendu, une gestion pratique de la situation actuelle reste nécessaire pour ne pas laisser cette question en suspens de manière préjudiciable.", "perfect": "Je maintiens le cadre horaire normalement applicable dans l''attente d''instructions différentes, cette position par défaut restant appropriée tant qu''aucune dérogation n''a été formellement validée.\n\nJe reste attentive aux nuisances éventuelles que cette sonorisation pourrait générer au-delà de l''horaire habituel, cette dimension restant pertinente indépendamment de l''issue de cette demande de dépassement.\n\nJe communique avec tact à cet élu que je reste dans l''attente d''un retour de ma hiérarchie, cette transparence pouvant l''aider à comprendre le processus en cours sans que cela ne soit perçu comme un refus définitif.\n\nJe reste attentive à l''évolution de la situation sur le terrain, cette vigilance continue restant nécessaire jusqu''à ce qu''une décision définitive soit communiquée.", "points": [{"position": 1, "label": "Maintenir le cadre horaire normalement applicable dans l''attente", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : position par défaut sans dérogation validée.", "groups": [{"position": 1, "keywords": ["cadre maintenu", "position par défaut", "dérogation non validée"]}]}, {"position": 2, "label": "Rester attentive aux nuisances éventuelles de cette sonorisation", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Dimension pertinente indépendamment de l''issue.", "groups": [{"position": 1, "keywords": ["nuisances surveillées", "dimension pertinente", "issue indépendante"]}]}, {"position": 3, "label": "Communiquer avec tact l''attente d''un retour hiérarchique", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Transparence sans refus définitif perçu.", "groups": [{"position": 1, "keywords": ["retour attendu communiqué", "transparence apportée", "pas de refus définitif"]}]}, {"position": 4, "label": "Rester attentive à l''évolution de la situation sur le terrain", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Vigilance jusqu''à la décision définitive.", "groups": [{"position": 1, "keywords": ["évolution surveillée", "vigilance continue", "décision définitive attendue"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('ordre-individu-provocateur-isole', '{"slug": "ordre-individu-provocateur-isole", "title": "Il s''approche du cordon et provoque nommément les agents", "theme_slug": "ordre-public", "difficulty": "moyen", "is_free": true, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 15 heures 30. Lors d''une manifestation, un individu isolé s''approche à plusieurs reprises du cordon que vous formez avec vos collègues, vous provoquant nommément par des propos insultants tout en sachant pertinemment que de nombreuses caméras de téléphones portables filment actuellement cette scène depuis les rangs des manifestants environnants. Cette provocation ciblée, qui semble délibérément chercher une réaction disproportionnée de votre part qui pourrait ensuite être diffusée et exploitée médiatiquement, nécessite une maîtrise de soi absolue face à cette tentative de déstabilisation personnelle.\n\nCette situation, où la présence de ces caméras transforme chaque geste et chaque parole en un élément potentiellement filmé et diffusé, impose une vigilance particulière sur l''ensemble de votre comportement face à cette provocation qui vous vise personnellement.\n\nCette configuration nécessite de faire preuve d''une maîtrise de soi exemplaire et de ne pas répondre à cette provocation, cette non-réaction restant la seule attitude appropriée face à cette tentative manifeste de vous faire réagir de manière disproportionnée.", "questions": [{"position": 1, "max_points": 5, "label": "Comment maintenez-vous votre maîtrise de soi face à cette provocation qui vous vise personnellement ?", "hint": "Cette provocation cherche délibérément une réaction de votre part, cette maîtrise de soi absolue restant la seule réponse appropriée à cette tentative de déstabilisation.", "perfect": "Je reste impassible face à ces propos insultants, cette maîtrise de soi restant essentielle pour ne pas offrir à cet individu la réaction qu''il recherche manifestement par cette provocation ciblée.\n\nJe reste consciente que cette provocation vise précisément à me faire sortir de mon rôle professionnel, cette compréhension m''aidant à maintenir ma posture malgré le caractère personnel de ces attaques.\n\nJe reste attentive à mon langage corporel autant qu''à mes paroles, cette vigilance globale restant nécessaire compte tenu de la présence de ces caméras qui pourraient capter tout signe de déstabilisation de ma part.\n\nJe ne réponds à aucun moment à ces provocations, cette non-réaction constituant la seule attitude professionnelle appropriée face à cette tentative délibérée de me faire réagir disproportionnément.", "points": [{"position": 1, "label": "Rester impassible face à ces propos insultants", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : ne pas offrir la réaction recherchée.", "groups": [{"position": 1, "keywords": ["impassibilité maintenue", "réaction non offerte", "provocation ciblée"]}]}, {"position": 2, "label": "Rester consciente que cette provocation vise à faire sortir de son rôle", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Compréhension aidant à maintenir la posture.", "groups": [{"position": 1, "keywords": ["rôle professionnel", "posture maintenue", "compréhension de la provocation"]}]}, {"position": 3, "label": "Rester attentive au langage corporel autant qu''aux paroles", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Vigilance globale face aux caméras présentes.", "groups": [{"position": 1, "keywords": ["langage corporel", "vigilance globale", "caméras présentes"]}]}, {"position": 4, "label": "Ne répondre à aucun moment à ces provocations", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Non-réaction comme seule attitude appropriée.", "groups": [{"position": 1, "keywords": ["non-réaction totale", "attitude appropriée", "tentative déjouée"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment gérez-vous la présence de ces caméras qui filment cette provocation depuis les rangs des manifestants ?", "hint": "Cette présence de caméras transforme chaque élément de cette interaction en un contenu potentiellement diffusé, cette réalité nécessitant une conscience particulière de cette dimension.", "perfect": "Je reste consciente que cette scène est probablement en train d''être filmée et pourrait être diffusée ultérieurement, cette conscience m''incitant à une rigueur professionnelle renforcée.\n\nJe ne cherche pas à masquer ou à empêcher cette captation, cette présence de caméras relevant d''un contexte que je ne peux ni ne dois chercher à contrôler dans ce type de situation publique.\n\nJe reste attentive à ce que mon comportement reste irréprochable indépendamment de cette diffusion potentielle, cette rigueur devant s''appliquer que je sois filmée ou non dans cette situation.\n\nJe reste concentrée sur ma mission de maintien de cette ligne du cordon, cette présence de caméras ne devant pas détourner mon attention de mes responsabilités opérationnelles.", "points": [{"position": 1, "label": "Rester consciente de cette captation probable et de sa diffusion possible", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : rigueur professionnelle renforcée par cette conscience.", "groups": [{"position": 1, "keywords": ["captation consciente", "diffusion possible", "rigueur renforcée"]}]}, {"position": 2, "label": "Ne pas chercher à masquer ou empêcher cette captation", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Contexte ne pouvant être contrôlé en situation publique.", "groups": [{"position": 1, "keywords": ["pas de tentative de masquage", "contexte public", "captation non contrôlée"]}]}, {"position": 3, "label": "Rester attentive à un comportement irréprochable indépendamment de la diffusion", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Rigueur s''appliquant filmée ou non.", "groups": [{"position": 1, "keywords": ["comportement irréprochable", "rigueur constante", "filmée ou non"]}]}, {"position": 4, "label": "Rester concentrée sur sa mission de maintien du cordon", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Caméras ne détournant pas des responsabilités opérationnelles.", "groups": [{"position": 1, "keywords": ["mission maintenue", "responsabilités opérationnelles", "attention non détournée"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment coordonnez-vous votre réponse avec vos collègues face à cette provocation ciblée ?", "hint": "Cette provocation, aussi individuellement ciblée soit-elle, nécessite une réponse coordonnée avec l''ensemble du dispositif plutôt qu''une gestion isolée de votre seule initiative.", "perfect": "Je signale discrètement à mes collègues cette provocation répétée, cette information restant utile pour une gestion coordonnée de cette situation par l''ensemble du cordon.\n\nJe reste attentive à ce qu''aucun de mes collègues ne réagisse non plus à cette provocation, cette cohésion collective restant essentielle pour ne pas offrir de prise à cette tentative de déstabilisation.\n\nJe reste attentive à signaler cette situation à un responsable si cette provocation venait à s''intensifier ou à dégénérer vers un comportement plus préoccupant que la seule insulte verbale.\n\nJe consigne mentalement les éléments de cette provocation pour un éventuel compte rendu ultérieur, cette documentation pouvant être utile si cette situation nécessitait un traitement complémentaire.", "points": [{"position": 1, "label": "Signaler discrètement cette provocation répétée aux collègues", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : gestion coordonnée par l''ensemble du cordon.", "groups": [{"position": 1, "keywords": ["provocation signalée", "gestion coordonnée", "cordon informé"]}]}, {"position": 2, "label": "S''assurer qu''aucun collègue ne réagisse non plus à cette provocation", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Cohésion collective essentielle.", "groups": [{"position": 1, "keywords": ["cohésion collective", "pas de réaction collègues", "prise non offerte"]}]}, {"position": 3, "label": "Signaler à un responsable si la provocation s''intensifie", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Vigilance sur une possible dégradation.", "groups": [{"position": 1, "keywords": ["responsable signalé", "intensification possible", "dégradation surveillée"]}]}, {"position": 4, "label": "Consigner mentalement les éléments pour un compte rendu ultérieur", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Documentation utile pour un traitement complémentaire.", "groups": [{"position": 1, "keywords": ["éléments consignés", "compte rendu ultérieur", "traitement complémentaire"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('ordre-mouvement-de-panique-fausse-alerte', '{"slug": "ordre-mouvement-de-panique-fausse-alerte", "title": "Une détonation de pétard, la foule reflue vers les sorties", "theme_slug": "ordre-public", "difficulty": "difficile", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 30, "situation_text": "Il est 23 heures. Lors d''un concert, une détonation de pétard retentit soudainement au sein de la foule, ce bruit soudain déclenchant un mouvement de panique généralisé où de nombreux spectateurs refluent précipitamment et de manière désordonnée vers les sorties disponibles, ce mouvement de foule en lui-même créant désormais un danger réel qui dépasse largement celui de l''événement initial parfaitement anodin qui l''a déclenché. Cette situation paradoxale, où le véritable danger provient de la réaction collective de panique plutôt que de cette détonation elle-même sans gravité, nécessite une action rapide et ciblée sur la gestion de ce mouvement de foule plutôt que sur l''incident initial qui l''a provoqué.\n\nCette configuration, caractéristique des situations où la panique elle-même devient le danger principal à gérer, impose de diffuser une information claire et rassurante pour stopper cette dynamique de panique avant qu''elle ne génère des conséquences physiques graves par simple effet de mouvement de foule.\n\nCette situation nécessite de diffuser sans délai une information claire à l''ensemble des personnes présentes pour désamorcer cette panique, cette communication rapide restant l''action prioritaire pour prévenir les risques bien réels que ce mouvement de foule désordonné pourrait engendrer.", "questions": [{"position": 1, "max_points": 5, "label": "Comment diffusez-vous sans délai une information claire pour stopper cette dynamique de panique ?", "hint": "Cette communication rapide et claire reste l''action prioritaire pour désamorcer cette panique avant qu''elle ne génère des conséquences physiques graves par le seul effet du mouvement de foule.", "perfect": "Je diffuse ou fais diffuser sans délai un message clair indiquant qu''il s''agissait d''un simple pétard sans danger réel, cette information factuelle étant essentielle pour désamorcer rapidement cette panique.\n\nJe m''assure que ce message soit audible du plus grand nombre possible, utilisant si nécessaire tous les moyens de sonorisation disponibles sur ce site pour toucher efficacement l''ensemble de la foule concernée.\n\nJe reste attentive à la clarté et à la simplicité de ce message, cette communication devant être immédiatement compréhensible par des personnes en état de panique et donc peu réceptives à des explications complexes.\n\nJe répète si nécessaire ce message rassurant, cette insistance restant utile pour toucher l''ensemble des personnes présentes et pour ancrer progressivement cette information rassurante.", "points": [{"position": 1, "label": "Diffuser sans délai un message clair sur l''absence de danger réel", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : information factuelle désamorçant la panique.", "groups": [{"position": 1, "keywords": ["message diffusé", "absence de danger", "panique désamorcée"]}]}, {"position": 2, "label": "S''assurer que ce message soit audible du plus grand nombre", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Moyens de sonorisation disponibles utilisés.", "groups": [{"position": 1, "keywords": ["message audible", "sonorisation utilisée", "foule touchée"]}]}, {"position": 3, "label": "Rester attentive à la clarté et simplicité de ce message", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Compréhensible par des personnes en état de panique.", "groups": [{"position": 1, "keywords": ["message clair et simple", "personnes en panique", "compréhension immédiate"]}]}, {"position": 4, "label": "Répéter si nécessaire ce message rassurant", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Toucher l''ensemble des personnes présentes.", "groups": [{"position": 1, "keywords": ["message répété", "ensemble touché", "information ancrée"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment gérez-vous concrètement ce mouvement de foule désordonné vers les sorties ?", "hint": "Au-delà de la seule communication, une gestion physique de ce mouvement de foule reste nécessaire pour prévenir les risques de bousculade et de chute lors de ce reflux précipité.", "perfect": "Je me positionne, avec mes collègues présents, pour orienter et fluidifier ce mouvement vers les sorties, cette action physique restant complémentaire à la communication verbale déjà engagée.\n\nJe reste attentive aux zones à risque de bousculade ou d''engorgement, ces points critiques nécessitant une attention particulière pour prévenir les chutes ou les compressions dans cette foule en mouvement.\n\nJe reste vigilante à toute personne qui pourrait chuter ou se trouver en difficulté durant ce mouvement, cette surveillance restant essentielle pour intervenir rapidement en cas de besoin.\n\nJe coordonne cette gestion avec l''ensemble des effectifs présents et le personnel de sécurité de cet événement, cette action collective restant nécessaire face à l''ampleur de ce mouvement de foule.", "points": [{"position": 1, "label": "Se positionner pour orienter et fluidifier le mouvement vers les sorties", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : action physique complémentaire à la communication.", "groups": [{"position": 1, "keywords": ["mouvement orienté", "fluidification", "action complémentaire"]}]}, {"position": 2, "label": "Rester attentive aux zones à risque de bousculade ou d''engorgement", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Points critiques nécessitant une attention particulière.", "groups": [{"position": 1, "keywords": ["zones à risque", "bousculade prévenue", "engorgement surveillé"]}]}, {"position": 3, "label": "Rester vigilante à toute personne en difficulté durant le mouvement", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Surveillance permettant une intervention rapide.", "groups": [{"position": 1, "keywords": ["personnes en difficulté", "surveillance continue", "intervention rapide"]}]}, {"position": 4, "label": "Coordonner cette gestion avec les effectifs et le personnel de sécurité", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Action collective face à l''ampleur du mouvement.", "groups": [{"position": 1, "keywords": ["coordination collective", "personnel de sécurité", "ampleur du mouvement"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment traitez-vous l''incident initial de cette détonation une fois la panique maîtrisée ?", "hint": "Une fois cette panique désamorcée, l''incident initial de cette détonation mérite un traitement propre pour identifier son origine et éviter toute réitération.", "perfect": "Je recherche, une fois la panique maîtrisée, l''origine précise de cette détonation, cette identification restant utile pour comprendre les circonstances de cet incident initial.\n\nJe recueille les témoignages de personnes ayant pu observer l''origine de ce pétard, ces éléments pouvant permettre d''identifier son auteur et les circonstances de cette action.\n\nJe reste attentive à la possibilité que cet acte, bien qu''ayant eu des conséquences limitées sur le plan matériel, puisse néanmoins constituer une infraction méritant un traitement approprié.\n\nJe consigne avec précision le déroulement de cet incident et de la panique qu''il a engendrée, cette documentation étant utile pour la suite du traitement de cette affaire et pour tirer les enseignements de cette gestion de crise.", "points": [{"position": 1, "label": "Rechercher l''origine précise de cette détonation une fois la panique maîtrisée", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : identification des circonstances de l''incident initial.", "groups": [{"position": 1, "keywords": ["origine recherchée", "panique maîtrisée", "circonstances identifiées"]}]}, {"position": 2, "label": "Recueillir les témoignages de personnes ayant observé l''origine", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Identification de l''auteur et des circonstances.", "groups": [{"position": 1, "keywords": ["témoignages recueillis", "auteur identifié", "circonstances précisées"]}]}, {"position": 3, "label": "Rester attentive à la possible infraction malgré les conséquences limitées", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Traitement approprié indépendamment de la gravité matérielle.", "groups": [{"position": 1, "keywords": ["infraction possible", "conséquences limitées", "traitement approprié"]}]}, {"position": 4, "label": "Consigner précisément le déroulement de l''incident et de la panique", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Documentation utile pour les enseignements de cette gestion.", "groups": [{"position": 1, "keywords": ["déroulement consigné", "enseignements tirés", "gestion de crise documentée"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('ordre-evacuation-batiment-recevant-public', '{"slug": "ordre-evacuation-batiment-recevant-public", "title": "Certains clients refusent de sortir sans leurs achats", "theme_slug": "ordre-public", "difficulty": "moyen", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 15 heures. Vous participez à l''évacuation d''un centre commercial suite à une alerte nécessitant de vider rapidement ce bâtiment recevant du public, cette opération étant ralentie par certains clients qui refusent de sortir sans avoir préalablement récupéré ou payé les achats qu''ils avaient en cours au moment du déclenchement de cette alerte. Cette résistance passive, motivée par un attachement compréhensible mais disproportionné à des considérations matérielles face à l''urgence de cette évacuation, complique le bon déroulement de cette opération de sécurité qui devrait normalement s''effectuer rapidement et sans complication.\n\nCette situation, où l''urgence de la sécurité collective entre en tension avec ces comportements individuels de résistance passive, nécessite une communication suffisamment claire et ferme pour obtenir cette évacuation sans pour autant recourir à une contrainte physique disproportionnée envers ces clients réticents.\n\nCette configuration impose d''obtenir cette évacuation par la clarté et la fermeté de votre message plutôt que par la contrainte, cette communication efficace restant l''outil principal pour surmonter cette résistance passive et accélérer le déroulement de cette opération de sécurité.", "questions": [{"position": 1, "max_points": 5, "label": "Comment obtenez-vous l''évacuation de ces clients réticents par la clarté de votre message plutôt que par la contrainte ?", "hint": "Cette communication claire et ferme doit rester l''outil principal pour surmonter cette résistance passive, la contrainte physique n''étant pas la réponse appropriée à ce type de comportement.", "perfect": "Je communique avec fermeté et clarté sur l''urgence réelle de cette évacuation, cette information devant primer sur les préoccupations matérielles que ces clients expriment face à leurs achats en cours.\n\nJe reste attentive à ne pas recourir à une contrainte physique disproportionnée face à cette résistance passive, cette réponse restant inappropriée pour ce type de comportement qui relève davantage d''une réticence que d''une opposition active.\n\nJe répète si nécessaire ce message avec insistance, cette persévérance restant nécessaire face à des personnes qui pourraient ne pas mesurer immédiatement la gravité de la situation qui justifie cette évacuation.\n\nJe reste ferme sur le principe de cette évacuation immédiate, sans pour autant entrer dans une négociation sur la possibilité de récupérer ces achats qui n''est manifestement pas envisageable dans ce contexte d''urgence.", "points": [{"position": 1, "label": "Communiquer avec fermeté et clarté sur l''urgence réelle de l''évacuation", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : urgence primant sur les préoccupations matérielles.", "groups": [{"position": 1, "keywords": ["fermeté et clarté", "urgence prioritaire", "préoccupations matérielles écartées"]}]}, {"position": 2, "label": "Ne pas recourir à une contrainte physique disproportionnée", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Réponse inappropriée à une résistance passive.", "groups": [{"position": 1, "keywords": ["pas de contrainte physique", "résistance passive", "réponse inappropriée"]}]}, {"position": 3, "label": "Répéter si nécessaire ce message avec insistance", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Persévérance face à une gravité non mesurée immédiatement.", "groups": [{"position": 1, "keywords": ["message répété", "insistance nécessaire", "gravité non mesurée"]}]}, {"position": 4, "label": "Rester ferme sans entrer dans une négociation sur les achats", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Récupération non envisageable dans ce contexte d''urgence.", "groups": [{"position": 1, "keywords": ["fermeté sans négociation", "récupération impossible", "contexte d''urgence"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment gérez-vous l''ensemble de cette évacuation pour qu''elle reste efficace malgré ces comportements individuels ?", "hint": "Cette évacuation d''ensemble doit rester efficace et rapide malgré ces comportements individuels de résistance, cette gestion collective restant prioritaire sur les cas particuliers.", "perfect": "Je reste concentrée sur l''efficacité globale de cette évacuation, ces comportements individuels de résistance ne devant pas me détourner de la gestion de l''ensemble de ce bâtiment à évacuer.\n\nJe sollicite si nécessaire l''aide du personnel de sécurité ou des employés de cet établissement, ces relais locaux pouvant utilement compléter mon action pour convaincre ces clients réticents.\n\nJe reste attentive à ne pas me focaliser excessivement sur ces cas particuliers au détriment du reste de cette opération d''évacuation qui nécessite une attention globale.\n\nJe reste vigilante sur le temps global de cette évacuation, ces retards ponctuels ne devant pas compromettre l''efficacité de l''ensemble de cette opération de sécurité.", "points": [{"position": 1, "label": "Rester concentrée sur l''efficacité globale de cette évacuation", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : gestion de l''ensemble du bâtiment.", "groups": [{"position": 1, "keywords": ["efficacité globale", "ensemble du bâtiment", "gestion collective"]}]}, {"position": 2, "label": "Solliciter l''aide du personnel de sécurité ou des employés", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Relais locaux complétant l''action.", "groups": [{"position": 1, "keywords": ["personnel sollicité", "relais locaux", "action complétée"]}]}, {"position": 3, "label": "Ne pas se focaliser excessivement sur ces cas particuliers", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Attention globale nécessaire au reste de l''opération.", "groups": [{"position": 1, "keywords": ["pas de focalisation excessive", "attention globale", "reste de l''opération"]}]}, {"position": 4, "label": "Rester vigilante sur le temps global de cette évacuation", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Retards ponctuels ne compromettant pas l''efficacité globale.", "groups": [{"position": 1, "keywords": ["temps global surveillé", "retards ponctuels", "efficacité préservée"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment rassurez-vous ces clients sur le sort de leurs achats une fois l''évacuation obtenue ?", "hint": "Une fois cette évacuation obtenue, une information rassurante sur le devenir de leurs achats en cours peut utilement compléter cette gestion sans pour autant compromettre l''urgence de la sortie.", "perfect": "Je les informe brièvement, une fois l''évacuation en cours, que leurs préoccupations sur ces achats seront traitées ultérieurement par l''établissement, cette information pouvant faciliter leur coopération.\n\nJe reste factuelle sur le fait que je ne peux pas moi-même garantir le sort de ces achats, cette précision évitant de créer de faux espoirs sur une question qui ne relève pas de ma compétence.\n\nJe les oriente, si le temps le permet brièvement, vers le personnel de cet établissement qui sera mieux à même de répondre à leurs questions sur ce point une fois cette évacuation terminée.\n\nJe reste attentive à ne pas passer un temps excessif sur cette dimension annexe, cette information rassurante devant rester brève pour ne pas retarder davantage cette évacuation prioritaire.", "points": [{"position": 1, "label": "Informer brièvement que leurs préoccupations seront traitées ultérieurement", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : information facilitant la coopération.", "groups": [{"position": 1, "keywords": ["information brève", "traitement ultérieur", "coopération facilitée"]}]}, {"position": 2, "label": "Rester factuelle sur l''incapacité à garantir le sort des achats", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Précision évitant de faux espoirs.", "groups": [{"position": 1, "keywords": ["factuelle sur l''incapacité", "pas de faux espoirs", "compétence limitée"]}]}, {"position": 3, "label": "Orienter vers le personnel de l''établissement pour cette question", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Réponse mieux adaptée une fois l''évacuation terminée.", "groups": [{"position": 1, "keywords": ["personnel orienté", "établissement compétent", "évacuation terminée"]}]}, {"position": 4, "label": "Ne pas passer un temps excessif sur cette dimension annexe", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Information brève ne retardant pas l''évacuation.", "groups": [{"position": 1, "keywords": ["temps limité", "information brève", "évacuation prioritaire"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('ordre-depart-bagarre-fete-locale', '{"slug": "ordre-depart-bagarre-fete-locale", "title": "Deux familles du village se prennent à partie devant la buvette", "theme_slug": "ordre-public", "difficulty": "moyen", "is_free": true, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 1 heure du matin. Lors d''une fête de village, deux familles bien connues de cette petite commune se prennent à partie devant la buvette, cette altercation prenant place dans un contexte où l''alcool a manifestement coulé toute la soirée et où votre effectif sur place reste particulièrement réduit compte tenu de l''heure tardive et de la taille modeste de cette localité rurale. Cette situation, où l''interconnaissance locale entre ces deux familles et l''ensemble des autres villageois présents complique singulièrement votre intervention, nécessite une gestion prudente compte tenu de votre isolement relatif face à ce début de conflit.\n\nCette configuration, caractéristique des interventions en milieu rural où chacun se connaît et où votre propre légitimité pourrait être perçue différemment que dans un contexte plus anonyme, impose une action mesurée qui tienne compte de ces spécificités locales tout en assurant la sécurité nécessaire face à ce début d''altercation.\n\nCette situation nécessite de séparer ces deux familles tout en demandant du renfort sans chercher à vous engager seule dans cette gestion d''une altercation qui pourrait rapidement dégénérer compte tenu de l''alcool consommé et du nombre de personnes potentiellement impliquées.", "questions": [{"position": 1, "max_points": 5, "label": "Comment séparez-vous ces deux familles sans vous engager seule dans cette gestion à risque ?", "hint": "Cette séparation doit être recherchée avec prudence, votre effectif réduit ne devant pas vous conduire à une intervention isolée qui pourrait s''avérer risquée face à ce début d''altercation.", "perfect": "Je cherche à créer une distance physique entre ces deux familles sans pour autant m''interposer physiquement de manière isolée, cette prudence restant nécessaire compte tenu de mon effectif réduit sur place.\n\nJe reste attentive à ne pas m''engager seule dans une intervention qui pourrait rapidement m''exposer si cette altercation venait à s''intensifier avec l''implication de plusieurs membres de ces deux familles.\n\nJe privilégie autant que possible le dialogue verbal pour tenter de calmer cette situation, cette approche restant moins risquée qu''une intervention physique directe dans ce contexte d''effectif limité.\n\nJe reste attentive aux personnes les plus virulentes dans chacune de ces deux familles, cette identification pouvant orienter utilement une intervention plus ciblée si celle-ci s''avérait nécessaire.", "points": [{"position": 1, "label": "Créer une distance physique sans interposition isolée", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : prudence compte tenu de l''effectif réduit.", "groups": [{"position": 1, "keywords": ["distance physique", "pas d''interposition isolée", "effectif réduit"]}]}, {"position": 2, "label": "Ne pas s''engager seule dans une intervention risquée", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Exposition possible si l''altercation s''intensifie.", "groups": [{"position": 1, "keywords": ["pas d''engagement seule", "exposition évitée", "altercation intensifiée"]}]}, {"position": 3, "label": "Privilégier le dialogue verbal pour calmer la situation", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Approche moins risquée que l''intervention physique directe.", "groups": [{"position": 1, "keywords": ["dialogue verbal", "approche moins risquée", "intervention physique évitée"]}]}, {"position": 4, "label": "Rester attentive aux personnes les plus virulentes de chaque famille", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Identification orientant une intervention ciblée.", "groups": [{"position": 1, "keywords": ["personnes virulentes identifiées", "intervention ciblée", "orientation utile"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment demandez-vous du renfort compte tenu de votre effectif réduit face à cette situation ?", "hint": "Cette demande de renfort reste essentielle face à votre isolement relatif, cette précaution restant nécessaire compte tenu du risque d''intensification de cette altercation.", "perfect": "Je sollicite sans délai un renfort compte tenu de mon effectif réduit sur place, cette précaution restant nécessaire face au risque que cette altercation ne s''intensifie avec l''implication de plusieurs personnes.\n\nJe précise clairement l''ampleur de cette situation dans ma demande, notamment le nombre de personnes potentiellement impliquées et le contexte d''alcoolisation qui pourrait compliquer cette gestion.\n\nJe reste attentive à la distance que ce renfort pourrait avoir à parcourir compte tenu de la localisation rurale de cette fête de village, cette réalité géographique pouvant influencer le délai d''intervention.\n\nJe reste vigilante en attendant ce renfort, cette période d''attente nécessitant une gestion prudente de la situation sans céder à la tentation d''une intervention isolée trop risquée.", "points": [{"position": 1, "label": "Solliciter sans délai un renfort compte tenu de l''effectif réduit", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : précaution face au risque d''intensification.", "groups": [{"position": 1, "keywords": ["renfort sollicité", "effectif réduit", "intensification possible"]}]}, {"position": 2, "label": "Préciser l''ampleur de la situation dans cette demande", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Nombre de personnes et contexte d''alcoolisation.", "groups": [{"position": 1, "keywords": ["ampleur précisée", "personnes impliquées", "alcoolisation signalée"]}]}, {"position": 3, "label": "Rester attentive à la distance que le renfort devra parcourir", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Réalité géographique influençant le délai.", "groups": [{"position": 1, "keywords": ["distance du renfort", "réalité rurale", "délai d''intervention"]}]}, {"position": 4, "label": "Rester vigilante en attendant ce renfort sans intervention isolée", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Gestion prudente durant l''attente.", "groups": [{"position": 1, "keywords": ["vigilance en attente", "pas d''intervention isolée", "gestion prudente"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment tenez-vous compte de cette interconnaissance locale dans votre gestion de cette altercation ?", "hint": "Cette interconnaissance entre ces familles et l''ensemble des villageois présents constitue une spécificité de ce contexte rural qui mérite d''être intégrée dans votre approche de cette situation.", "perfect": "Je reste consciente que cette interconnaissance locale peut à la fois compliquer et faciliter ma gestion de cette situation, certains villageois pouvant m''aider à apaiser ce conflit compte tenu de leur proximité avec ces deux familles.\n\nJe reste attentive à ne pas prendre parti pour l''une ou l''autre de ces familles, cette neutralité restant essentielle pour préserver ma légitimité future dans cette commune où je pourrais être amenée à intervenir à nouveau.\n\nJe reste consciente que mon intervention sera probablement commentée et connue de l''ensemble de cette petite communauté, cette réalité m''incitant à une rigueur professionnelle particulière dans ce contexte de forte interconnaissance.\n\nJe sollicite si pertinent l''aide de personnes respectées localement qui pourraient contribuer à apaiser cette situation, cette ressource locale pouvant compléter utilement mon action dans ce contexte rural spécifique.", "points": [{"position": 1, "label": "Rester consciente que cette interconnaissance peut compliquer et faciliter la gestion", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : villageois pouvant aider à apaiser le conflit.", "groups": [{"position": 1, "keywords": ["interconnaissance reconnue", "villageois aidants", "conflit apaisé"]}]}, {"position": 2, "label": "Ne pas prendre parti pour l''une ou l''autre des familles", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Neutralité préservant la légitimité future.", "groups": [{"position": 1, "keywords": ["neutralité maintenue", "légitimité future", "pas de parti pris"]}]}, {"position": 3, "label": "Rester consciente que l''intervention sera connue de la communauté", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Rigueur professionnelle dans ce contexte de forte interconnaissance.", "groups": [{"position": 1, "keywords": ["intervention connue", "communauté informée", "rigueur particulière"]}]}, {"position": 4, "label": "Solliciter l''aide de personnes respectées localement si pertinent", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Ressource locale complétant l''action.", "groups": [{"position": 1, "keywords": ["personnes respectées", "ressource locale", "action complétée"]}]}]}]}'::jsonb);